final class Seeder{public static function reset(string $root,string $path,string $uploadDir):PDO{$absolute=str_starts_with($path,'/')?$path:$root.'/'.$path;if(is_file($absolute))unlink($absolute);$db=Database::connect($absolute);$db->exec((string)file_get_contents($root.'/database/schema.sql'));$hash=password_hash('Password123!',PASSWORD_DEFAULT);$users=[['author@example.test',$hash,'Avery Author','author','Northstar University'],['coauthor@example.test',$hash,'Casey Coauthor','author','Lakeside Institute'],['reviewer@example.test',$hash,'Riley Reviewer','reviewer','Peer Review Lab'],['reviewer2@example.test',$hash,'Jordan Reviewer','reviewer','Systems Institute'],['chair@example.test',$hash,'Cameron Chair','chair','Program Committee'],['admin@example.test',$hash,'Alex Admin','admin','Conference Office']];$st=$db->prepare('INSERT INTO users(email,password_hash,name,role,affiliation) VALUES(?,?,?,?,?)');foreach($users as $u)$st->execute($u);$db->exec("INSERT INTO conferences(name,slug,active_phase) VALUES('Synthetic Software Engineering Conference 2027','ssec-2027','submission')");$db->exec('INSERT INTO conference_chairs(conference_id,user_id) VALUES(1,5)');$db->exec("INSERT INTO conference_phases(conference_id,phase,starts_at,ends_at,status) VALUES(1,'submission','2026-01-01T00:00:00Z','2026-09-01T00:00:00Z','active'),(1,'review','2026-09-02T00:00:00Z','2026-11-01T00:00:00Z','inactive'),(1,'rebuttal','2026-11-02T00:00:00Z','2026-11-15T00:00:00Z','inactive'),(1,'decision','2026-11-16T00:00:00Z','2027-01-15T00:00:00Z','inactive')");$db->exec("INSERT INTO submissions(conference_id,title,abstract,keywords_json,track,status) VALUES(1,'Repository-Guided Program Repair','A study of repository context for repair.','[\"program repair\",\"repository context\"]','Research','submitted'),(1,'Accessible Developer Tools','An empirical study of accessible tooling.','[\"accessibility\",\"developer tools\"]','Industry','submitted')");$db->exec('INSERT INTO submission_authors(submission_id,user_id,author_order,is_corresponding) VALUES(1,1,1,1),(1,2,2,0),(2,2,1,1)');$dir=str_starts_with($uploadDir,'/')?$uploadDir:$root.'/'.$uploadDir;if(!is_dir($dir))mkdir($dir,0775,true);$pdf="%PDF-1.4\n% Synthetic blinded manuscript\n1 0 obj<</Type/Catalog>>endobj\n%%EOF\n";file_put_contents($dir.'/seed-paper.pdf',$pdf);$db->prepare('INSERT INTO stored_files(original_name,stored_name,mime_type,size_bytes) VALUES(?,?,?,?)')->execute(['paper-1.pdf','seed-paper.pdf','application/pdf',strlen($pdf)]);$db->exec('INSERT INTO manuscripts(submission_id,file_id,version,uploaded_by) VALUES(1,1,1,1)');$db->exec("INSERT INTO review_assignments(submission_id,reviewer_id,status,assigned_by) VALUES(1,3,'assigned',5)");$db->exec("INSERT INTO reviews(assignment_id,scores_json,confidence,summary,comments_to_authors,confidential_comments,status) VALUES(1,'{\"overall\":3,\"novelty\":4}',4,'Promising work.','Clarify the evaluation setup.','No confidential concerns.','draft')");$db->exec("INSERT INTO notifications(user_id,type,message,link) VALUES(1,'submission','Submission 1 was received.','/submissions/1'),(3,'assignment','A paper was assigned for review.','/assignments/1'),(5,'activity','A new paper was submitted.','/submissions/1')");$db->exec("INSERT INTO submission_activity(submission_id,actor_id,event,details) VALUES(1,1,'submission_created','Initial submission received.'),(1,5,'reviewer_assigned','One reviewer assigned.')");return$db;}}
